<template>
  <div class="flex flex-col gap-4">
    <div>
      <h3 class="text-lg font-semibold">Share referral link</h3>
      <p class="text-sm text-muted-foreground mt-1">
        Copy and share this link directly. Anyone who signs up through it will be tracked as your referral.
      </p>
    </div>
    <div class="rounded-xl bg-accent/50 p-5 flex-1 flex items-center">
      <div class="flex justify-center gap-2 flex-col md:flex-row cursor-pointer w-full" @click="copyLinkToClipboard">
        <div class="w-full grid py-2 px-4 rounded-lg bg-background border">
          <p class="w-full truncate m-auto font-semibold underline text-base text-center">{{ referralLink }}</p>
        </div>
        <Button
          type="button"
          variant="outline"
          class="grid justify-items-center h-10 w-full md:size-auto md:aspect-square rounded-lg"
        >
          <Check v-if="isCopied" class="h-4 w-4" />
          <Copy v-else class="h-4 w-4" />
        </Button>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { Check, Copy } from 'lucide-vue-next';
import { useRouter } from 'vue-router';

interface Props {
  referralCode: string;
  appBaseUrl: string;
}

const props = defineProps<Props>();

const referralCode = computed(() => props.referralCode);

const { resolve } = useRouter();
const referralLink = computed(
  () => new URL(resolve({ name: 'sign-up', query: { referral_code: referralCode.value } }).href, props.appBaseUrl).href
);

const { isCopied, copy } = useCopyToClipboard();

async function copyLinkToClipboard() {
  await copy(referralLink.value);
}
</script>
